    /// <summary>
    /// Sets company information, logo and other common report header information to <c>CustAccountStatementExtTmp</c> table buffer.
    /// </summary>
    protected void setCommonData()
    {
        next setCommonData();
        custAccountStatementExtTmp.KPMGCompanyEmail = statementCompanyInfo.email();

        // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - Start
        // Footer company bank info
        custAccountStatementExtTmp.KPMGRegNum           = statementCompanyInfo.RegNum;
        custAccountStatementExtTmp.KPMGBankAccountNum   = BankAccountTable::find(statementCompanyInfo.Bank).AccountNum;
        custAccountStatementExtTmp.KPMGRemittanceEmail  = this.getStatement(statementCompanyInfo, LogisticsElectronicAddressMethodType::Email);
        custAccountStatementExtTmp.KPMGCustServiceNum   = this.getStatement(statementCompanyInfo, LogisticsElectronicAddressMethodType::Phone);
        custAccountStatementExtTmp.KPMGFooterNote       = this.parmContract().parmFooterNote();
        // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - End
    }

    /// <summary>
    /// MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021
    /// Footer BPay info
    /// </summary>
    /// <param name = "_custCurrencyIndex">The customer currency index</param>
    protected void populateCustAccountStatementExtTmp(int _custCurrencyIndex)
    {
        METCustTable metCustTable;

        next populateCustAccountStatementExtTmp(_custCurrencyIndex);

        if (custPre)
        {
            metCustTable = METCustTable::find(currentCust.accountNum);
            custAccountStatementExtTmp.KPMGBPayBillerCode   = metCustTable.BPayBillerCode;
            custAccountStatementExtTmp.KPMGBPayReference    = metCustTable.BPayReference;
        }

        if (cust_Trans)
        {
            custAccountStatementExtTmp.CustTrans_TransDate = currentTrans.DocumentDate;
        }
    }

    /// <summary>
    /// MPJ_4044_CustomerAccountStatement - kscerri - 22/07/2021
    /// </summary>
    /// <param name = "_companyInfo">Company info record</param>
    /// <param name = "_Type">pick remit to type email or phone</param>
    /// <returns>email or phone details</returns>
    public LogisticsElectronicAddressLocator getStatement(CompanyInfo _companyInfo, LogisticsElectronicAddressMethodType _Type)
    {        
        DirPartyLocation            dirPartyLocation;
        LogisticsElectronicAddress  logisticsElectronicAddress;
        str remitTo = enum2Str(LogisticsLocationRoleType::RemitTo);

        select firstonly Locator from  logisticsElectronicAddress
            exists join dirPartyLocation
                where logisticsElectronicAddress.location               == dirPartyLocation.location
                   && dirPartyLocation.Party                            == _companyInfo.RecId
                   && logisticsElectronicAddress.type                   == _Type
                   && logisticsElectronicAddress.ElectronicAddressRoles == remitTo;
               
        return logisticsElectronicAddress.Locator;
    }
